// ---------- the request ----------

/** A Gmail message or conversation id, as Gmail writes them: letters and digits. Anything else is never sent to Gmail. */
const GMAIL_ID = /^[A-Za-z0-9_-]{1,64}$/
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
const PAGE_TOKEN = /^[A-Za-z0-9_-]{1,256}$/

/** The longest search the tab may send. */
export const MY_MAIL_QUERY_MAX = 500

const VIEWS: readonly MyMailView[] = ['toTag', 'tagged', 'all']
const LABELS: readonly MyMailLabel[] = ['INBOX', 'SENT']
const JOB_KINDS: readonly MyMailJobKind[] = ['bid', 'project', 'pipeline']

/**
 * A request as the tab posts it (`MyMailRequest`), read strictly, or null and the function answers `badRequest`. A list
 * with no view reads as To tag; its search is trimmed; its labels are Gmail's INBOX and SENT alone, once each, both when
 * none are named. A job's id is a uuid, kept lower-case so it keys as the database keys it.
 */
export function parseMyMailRequest(raw: unknown): MyMailRequest | null {
  if (!raw || typeof raw !== 'object') return null
  const r = raw as Record<string, unknown>
  switch (r.action) {
    case 'list': {
      const view = r.view === undefined || r.view === null ? 'toTag' : VIEWS.find((v) => v === r.view)
      if (!view) return null
      if (r.q !== undefined && r.q !== null && typeof r.q !== 'string') return null
      const q = typeof r.q === 'string' ? r.q.trim() : ''
      if (q.length > MY_MAIL_QUERY_MAX) return null
      const token = r.pageToken
      if (token !== undefined && token !== null && (typeof token !== 'string' || !PAGE_TOKEN.test(token))) return null
      let labels: MyMailLabel[] = []
      if (r.labels !== undefined && r.labels !== null) {
        if (!Array.isArray(r.labels)) return null
        const picked = r.labels.map((l) => LABELS.find((x) => x === l))
        if (picked.some((l) => !l)) return null
        labels = LABELS.filter((l) => picked.includes(l))
      }
      return { action: 'list', view, ...(q ? { q } : {}), ...(typeof token === 'string' ? { pageToken: token } : {}), ...(labels.length > 0 ? { labels } : {}) }
    }
    case 'open':
      return typeof r.gmailId === 'string' && GMAIL_ID.test(r.gmailId) ? { action: 'open', gmailId: r.gmailId } : null
    case 'tag': {
      const job = r.job
      if (typeof r.threadId !== 'string' || !GMAIL_ID.test(r.threadId) || !job || typeof job !== 'object') return null
      const j = job as Record<string, unknown>
      const kind = JOB_KINDS.find((k) => k === j.kind)
      if (!kind || typeof j.id !== 'string' || !UUID.test(j.id)) return null
      return { action: 'tag', threadId: r.threadId, job: { kind, id: j.id.toLowerCase() } }
    }
    case 'untag':
      return typeof r.threadId === 'string' && GMAIL_ID.test(r.threadId) ? { action: 'untag', threadId: r.threadId } : null
    default:
      return null
  }
}

// ---------- the search a page reads ----------

/**
 * The person's own search, fenced: its brackets and braces taken out, and its quotes too when they do not pair, so it can
 * never close the group it sits in and reach past the fence's terms. Wrapped as one group; '' when nothing is left.
 */
export function fencedQuery(q: string): string {
  let s = q.replace(/[(){}]/g, ' ')
  if ((s.match(/"/g) ?? []).length % 2 === 1) s = s.replace(/"/g, ' ')
  s = s.replace(/\s+/g, ' ').trim()
  return s ? `(${s})` : ''
}

/**
 * The Gmail search one page of the list reads: the Inbox and the Sent box, or the one asked for; never Drafts, Spam,
 * Trash or Chats; never a label the person left out (`users.my_mail_hidden_labels`, by name); and the person's own search
 * as one group. Tagged reads only mail carrying the tag's label (`MY_MAIL_GMAIL_LABEL`, which a tag puts on every mail it
 * lands) and To tag never does, so neither page fills with mail its view hides; `viewRows` still decides what is drawn.
 */
export function myMailQuery(input: { view: MyMailView; labels?: readonly MyMailLabel[]; hidden?: readonly string[]; q?: string }): string {
  const asked = input.labels && input.labels.length > 0 ? LABELS.filter((l) => input.labels!.includes(l)) : LABELS
  const boxes = asked.map((l) => (l === 'INBOX' ? 'in:inbox' : 'in:sent'))
  const parts = [boxes.length > 1 ? `(${boxes.join(' OR ')})` : boxes[0]!, '-in:drafts', '-in:spam', '-in:trash', '-in:chats']
  const seen = new Set<string>()
  for (const name of input.hidden ?? []) {
    const label = name.replace(/"/g, '').replace(/\s+/g, ' ').trim()
    if (!label || seen.has(label.toLowerCase())) continue
    seen.add(label.toLowerCase())
    parts.push(`-label:"${label}"`)
  }
  if (input.view === 'tagged') parts.push(`label:"${MY_MAIL_GMAIL_LABEL}"`)
  if (input.view === 'toTag') parts.push(`-label:"${MY_MAIL_GMAIL_LABEL}"`)
  const own = fencedQuery(input.q ?? '')
  if (own) parts.push(own)
  return parts.join(' ')
}

/** How many messages a list reads whole at once: Gmail counts 5 units a read and lets a box spend 250 a second. */
export const MY_MAIL_READ_CHUNK = 10

/** A message Gmail files as a draft, in Spam or Trash, or a chat: never read for the tab, never written by a tag. */
export function neverRead(labels: readonly string[] | undefined): boolean {
  return (labels ?? []).some((l) => Object.prototype.hasOwnProperty.call(MY_MAIL_NEVER_LABELS, l))
}

// ---------- how a refusal answers ----------

/** The HTTP status each refusal answers with (`docs/EDGE_FUNCTIONS.md` → gmail-mine). */
export const MY_MAIL_REFUSAL_STATUS: Readonly<Record<MyMailRefusalError, number>> = {
  signIn: 401,
  readOnly: 403,
  officeOnly: 403,
  off: 403,
  offWorkspace: 403,
  badRequest: 400,
  notFound: 404,
  google: 502,
}

/**
 * The status of a step the database or the bucket refused mid-way. Its refusal is `google`, the one kind that says try
 * again: the contract has no kind of its own for a server's failure, and the tab shows the words as they come.
 */
export const MY_MAIL_STOPPED_STATUS = 500

/** Our words, then who said what after them, ending on a stop. */
function withReason(ours: string, said: string, reason: string): string {
  const r = reason.replace(/\s+/g, ' ').trim()
  return r ? `${ours} ${said}: ${/[.!?]$/.test(r) ? r : `${r}.`}` : ours
}

/** The reasons Google's token exchange gives for an address it will not hand the app. */
const REFUSED_GRANT = /\b(?:unauthorized_client|invalid_grant|access_denied|admin_policy_enforced)\b/i

/**
 * A failed token exchange (`_shared/googleToken.ts` throws `Google token exchange failed (<status>): <reason>`). A 400,
 * 401 or 403, or Google's `unauthorized_client` or `invalid_grant`, is an address the delegation will not read: off the
 * company's Workspace (the dev's own address), or not covered by it. Ours, then Google's reason. Anything else is
 * Google's own failure.
 */
export function tokenRefusal(message: string): MyMailRefusal {
  const m = /Google token exchange failed \((\d{3})\):\s*([\s\S]*)$/.exec(message)
  const status = m ? Number(m[1]) : null
  const reason = (m ? m[2]! : message).trim()
  const kind: MyMailRefusalError = (status !== null && [400, 401, 403].includes(status)) || REFUSED_GRANT.test(reason) ? 'offWorkspace' : 'google'
  return myMailRefusal(kind, withReason(MY_MAIL_REFUSAL_WORDS[kind], m ? 'Google said' : 'The reason', reason))
}

/**
 * A Gmail call that failed (`_shared/gmail.ts`'s `GmailError`, `Gmail <path> failed (<status>): <reason>`): a mail or a
 * conversation Gmail no longer has is `notFound` when the call named one (`missing`); anything else is Google's own
 * failure, ours then Gmail's reason.
 */
export function gmailRefusal(e: { status?: number | null; message: string }, missing = false): MyMailRefusal {
  if (missing && e.status === 404) return myMailRefusal('notFound')
  const m = /failed \((\d{3})\):\s*([\s\S]*)$/.exec(e.message)
  return myMailRefusal('google', withReason(MY_MAIL_REFUSAL_WORDS.google, m ? 'Gmail said' : 'The reason', m ? m[2]! : e.message))
}

/**
 * A step the database or the bucket refused: what stopped, that what was done stays, and the reason, the database's
 * unless `said` names another speaker.
 */
export function stoppedRefusal(what: string, reason: string, said = 'The database said'): MyMailRefusal {
  return myMailRefusal('google', withReason(`${what.trim()} What was done stays. Try again in a minute.`, said, reason))
}

// ---------- the mail, for the reader ----------

/** The most HTML an open answers: a longer body is left to its words (`bodyText`). */
export const MY_MAIL_HTML_MAX = 500_000

const headersOf = (part: GmailPart): Record<string, string> => {
  const out: Record<string, string> = {}
  for (const h of part.headers ?? []) {
    const key = h.name.trim().toLowerCase()
    if (key && !(key in out)) out[key] = h.value
  }
  return out
}

const decodeBytes = (bytes: Uint8Array, charset: string | null): string => {
  try {
    return new TextDecoder(charset || 'utf-8').decode(bytes)
  } catch {
    return new TextDecoder('utf-8').decode(bytes)
  }
}

/**
 * A mail's HTML as it was sent, for the reader to sanitise and draw: each HTML part that is not a file, in order, read by
 * its charset as the bids@ reader's parser reads the words. Null when the mail has none, or more than an open answers.
 */
export function myMailBodyHtml(message: Pick<GmailMessage, 'payload'>): string | null {
  const parts: string[] = []
  const walk = (part: GmailPart) => {
    const mime = (part.mimeType ?? '').toLowerCase()
    if (mime.startsWith('multipart/')) {
      for (const kid of part.parts ?? []) walk(kid)
      return
    }
    const own = headersOf(part)
    if (mime !== 'text/html' || part.filename || /^\s*attachment/i.test(own['content-disposition'] ?? '')) return
    const charset = /charset="?([^";\s]+)"?/i.exec(own['content-type'] ?? '')?.[1] ?? null
    parts.push(decodeBytes(base64UrlBytes(part.body?.data ?? ''), charset))
  }
  if (message.payload) walk(message.payload)
  const html = parts.join('\n').trim()
  return html && html.length <= MY_MAIL_HTML_MAX ? html : null
}

/** A header's addresses as the tab draws them: the name trimmed ('' for none) and the address. */
export function myMailParties(list: readonly EmailAddress[]): MyMailParty[] {
  return list.map((a) => ({ name: a.name?.trim() ?? '', address: a.address.trim() }))
}

/** The files a mail carries, as the row counts them: a small picture placed in the body (a signature's logo) left out. */
export function myMailFileList(email: Pick<EmailIn, 'files'>): MyMailFile[] {
  return email.files.filter((f) => fileKeep(f) !== 'skip').map((f) => ({ name: f.name, mime: f.mime, size: f.size }))
}

// ---------- which jobs are open, and their chips ----------

/** A bid as the guess reads it: its number and name, and its outcome. */
export interface MyMailBidRow extends SubjectBidRow {
  outcome: string | null
}

/** A GC project: its `projects` row's number and name, with its `gc_projects` row's stage and the day it was lost. */
export interface MyMailProjectRow extends SubjectProjectRow {
  stage: string | null
  lost_on: string | null
}

/** A Pipeline job: its numbers, its name, its status, and the customers on it (the billed one and the GC). */
export interface MyMailPipelineRow extends SubjectPipelineRow {
  status: string | null
  customer_id: string | null
  gc_customer_id: string | null
}

/**
 * Whether a job is open, for the guess (`mailGuess.ts`, steps 3 and 4): a job that is not finished. A bid is open while
 * it has no outcome (not won, lost, or started or complete); a GC project while it is not closed and was not lost; a
 * Pipeline job until it is paid, since a billed job still draws mail about its money. Simple on purpose: a guess is only
 * ever offered with a Yes.
 */
export const bidIsOpen = (row: Pick<MyMailBidRow, 'outcome'>): boolean => !(row.outcome ?? '').trim()
export const gcProjectIsOpen = (row: Pick<MyMailProjectRow, 'stage' | 'lost_on'>): boolean => (row.stage ?? '').trim().toLowerCase() !== 'closed' && !row.lost_on
export const pipelineIsOpen = (row: Pick<MyMailPipelineRow, 'status'>): boolean => (row.status ?? '').trim().toLowerCase() !== 'paid'

/** The jobs a page read, by kind: GC projects only (a `projects` row `gc_projects` does not hold is no job here). */
export interface MyMailJobRows {
  bids: readonly MyMailBidRow[]
  projects: readonly MyMailProjectRow[]
  pipeline: readonly MyMailPipelineRow[]
  prefixes: LedgerPrefixMap
}

/** Every job the rows hold as `subjectJobs` lists it (no `mine` yet), its chip, and whether it is open, by key. */
export function myMailJobs(rows: MyMailJobRows): { jobs: SubjectJob[]; chips: Record<string, MyMailJobChip>; open: Record<string, boolean> } {
  const jobs = subjectJobs(rows, new Set())
  const chips: Record<string, MyMailJobChip> = {}
  for (const j of jobs) {
    const chip = subjectJobChip(j)
    if (chip) chips[j.key] = chip
  }
  const open: Record<string, boolean> = {}
  for (const b of rows.bids) open[jobKey({ kind: 'bid', id: b.id })] = bidIsOpen(b)
  for (const p of rows.projects) open[jobKey({ kind: 'project', id: p.id })] = gcProjectIsOpen(p)
  for (const j of rows.pipeline) open[jobKey({ kind: 'pipeline', id: j.id })] = pipelineIsOpen(j)
  return { jobs, chips, open }
}

// ---------- the facts a page's guesses read ----------

/** An address as `contact_channel_key('email', …)` keys it: trimmed and lower-case, '' when it is not one. */
export function myMailAddressKey(address: string | null | undefined): string {
  const a = (address ?? '').trim().toLowerCase()
  return a.includes('@') ? a : ''
}

/** A domain safe to name in a PostgREST filter: letters, digits, dashes and dots, with a dot. */
const SAFE_DOMAIN = /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$/

/** Our own domains: the person's, the boxes' and the app's sender's. A domain of ours never names a customer. */
export function myMailOurDomains(addresses: Iterable<string>): Set<string> {
  const out = new Set<string>()
  for (const a of addresses) {
    const d = domainOf(a)
    if (d) out.add(d)
  }
  return out
}

/**
 * What a page's guesses need read: the other parties' addresses (by key), the subjects' numbers (`subjectNumbers`, as the
 * bids@ reader reads them), and the parties' domains worth asking about: never an open mail service's, never ours.
 */
export function myMailGuessAsks(rows: readonly Pick<MyMailRow, 'who' | 'subject'>[], ourDomains: Iterable<string>): { addresses: string[]; numbers: string[]; domains: string[] } {
  const ours = new Set([...ourDomains].map((d) => d.trim().toLowerCase()))
  const addresses = new Set<string>()
  const numbers = new Set<string>()
  const domains = new Set<string>()
  for (const r of rows) {
    const key = myMailAddressKey(r.who.address)
    if (key) addresses.add(key)
    if (r.subject !== MY_MAIL_NO_SUBJECT) for (const n of subjectNumbers(r.subject)) numbers.add(n)
    const d = domainOf(key)
    if (d && SAFE_DOMAIN.test(d) && !OPEN_MAIL_DOMAINS.has(d) && !ours.has(d)) domains.add(d)
  }
  return { addresses: [...addresses], numbers: [...numbers], domains: [...domains] }
}

/** A PostgREST `or` over the columns ending on any of the domains (`<column>.ilike.*@<domain>`), safe domains alone. */
export function domainFilter(columns: readonly string[], domains: readonly string[]): string {
  return domains
    .filter((d) => SAFE_DOMAIN.test(d))
    .flatMap((d) => columns.map((c) => `${c}.ilike.*@${d}`))
    .join(',')
}

/** The contacts each address is on, by its key, from `contact_channels` rows of kind email. */
export function contactsByAddress(rows: readonly { contact_id: string; key?: string | null; value?: string | null }[]): Record<string, string[]> {
  const out: Record<string, string[]> = {}
  for (const r of rows) {
    const key = myMailAddressKey(r.key || r.value)
    if (!key) continue
    const list = (out[key] ??= [])
    if (!list.includes(r.contact_id)) list.push(r.contact_id)
  }
  return out
}

/** Each contact's jobs (`contact_jobs`), by contact id: the job's key and whether it is the contact's star (`is_default`). */
export function contactJobsOf(
  rows: readonly { contact_id: string; bid_id: string | null; project_id: string | null; jobs_ledger_id: string | null; is_default?: boolean | null }[],
): Record<string, { key: string; star: boolean }[]> {
  const out: Record<string, { key: string; star: boolean }[]> = {}
  for (const r of rows) {
    const key = jobKeyOfRow(r)
    if (!key) continue
    const list = (out[r.contact_id] ??= [])
    const had = list.find((t) => t.key === key)
    if (had) had.star = had.star || r.is_default === true
    else list.push({ key, star: r.is_default === true })
  }
  return out
}

/** A customer as the domain step reads it: its name and its own emails. */
export interface MyMailCustomerRow {
  id: string
  name: string | null
  contact_info?: unknown
  billing_email?: string | null
}

/** One of a customer's contact persons, by email. */
export interface MyMailCustomerPersonRow {
  customer_id: string
  email: string | null
}

/**
 * The customers on each domain: one whose own email (`contact_info.email`, `billing_email`) or one of whose contact
 * persons' emails is on it. `customers` holds every customer the persons point at too; one with no name says nothing.
 */
export function domainCustomers(
  domains: readonly string[],
  customers: readonly MyMailCustomerRow[],
  persons: readonly MyMailCustomerPersonRow[],
): Record<string, { customerId: string; name: string }[]> {
  const wanted = new Set(domains)
  const byId = new Map(customers.map((c) => [c.id, c]))
  const out: Record<string, { customerId: string; name: string }[]> = {}
  const add = (address: unknown, customerId: string) => {
    const d = typeof address === 'string' ? domainOf(address) : ''
    const name = byId.get(customerId)?.name?.trim() ?? ''
    if (!d || !wanted.has(d) || !name) return
    const list = (out[d] ??= [])
    if (!list.some((x) => x.customerId === customerId)) list.push({ customerId, name })
  }
  for (const c of customers) {
    const own = c.contact_info && typeof c.contact_info === 'object' ? (c.contact_info as Record<string, unknown>).email : null
    add(own, c.id)
    add(c.billing_email, c.id)
  }
  for (const p of persons) add(p.email, p.customer_id)
  return out
}

/** Each customer's open Pipeline jobs, by key: the jobs it is the billed customer on, or the GC of. */
export function customerOpenJobs(pipeline: readonly MyMailPipelineRow[]): Record<string, string[]> {
  const out: Record<string, string[]> = {}
  for (const j of pipeline) {
    if (!pipelineIsOpen(j)) continue
    const key = jobKey({ kind: 'pipeline', id: j.id })
    for (const c of new Set([j.customer_id, j.gc_customer_id])) {
      if (!c) continue
      const list = (out[c] ??= [])
      if (!list.includes(key)) list.push(key)
    }
  }
  return out
}

/** What one page read for its guesses, the function's reads folded into plain maps. */
export interface MyMailPageFacts {
  /** Every job the page's subjects or parties may name, as `subjectJobs` lists them, `mine` not yet set. */
  jobs: readonly SubjectJob[]
  chips: Readonly<Record<string, MyMailJobChip>>
  open: Readonly<Record<string, boolean>>
  contactsByAddress: Readonly<Record<string, readonly string[]>>
  contactJobs: Readonly<Record<string, readonly { key: string; star: boolean }[]>>
  domainCustomers: Readonly<Record<string, readonly { customerId: string; name: string }[]>>
  customerOpenJobs: Readonly<Record<string, readonly string[]>>
}

/**
 * One row's facts for `guessJob`, from what its page read. The other party's contact is the one their address is on,
 * when it is on one alone: two contacts on one address say nothing about which. Its jobs are the subject's `mine` (the
 * bids@ reader's `jobFor` reads the sender's own jobs the same way) and the party's jobs, each with its star and whether
 * it is open. Each customer on the party's domain gives its one open Pipeline job; a customer with two gives none.
 */
export function myMailGuessFacts(row: Pick<MyMailRow, 'who'>, page: MyMailPageFacts, taggedJob: MyMailJobChip | null = null): MyMailGuessFacts {
  const address = myMailAddressKey(row.who.address)
  const contacts = page.contactsByAddress[address] ?? []
  const contact = contacts.length === 1 ? contacts[0]! : null
  const ties = contact ? (page.contactJobs[contact] ?? []) : []
  const mine = new Set(ties.map((t) => t.key))
  const partyJobs = ties.flatMap((t) => {
    const chip = page.chips[t.key]
    return chip ? [{ chip, star: t.star, open: page.open[t.key] === true }] : []
  })
  const domainJobs = (page.domainCustomers[domainOf(address)] ?? []).flatMap((c) => {
    const keys = page.customerOpenJobs[c.customerId] ?? []
    const chip = keys.length === 1 ? page.chips[keys[0]!] : undefined
    return chip ? [{ chip, customer: c.name }] : []
  })
  return { subjectJobs: page.jobs.map((j) => ({ ...j, mine: mine.has(j.key) })), partyJobs, domainJobs, taggedJob }
}

/** A line as the function reads one: its id and its job, whose box it came from, and who last tied it. */
export interface MyMailLine {
  id: string
  bid_id: string | null
  project_id: string | null
  jobs_ledger_id: string | null
  mail_user_id?: string | null
  tied_by?: string | null
}

/**
 * A row with what the database holds: the tagged conversation's chip with this mail's line on it, the line that holds
 * this mail (the boxes', or an earlier tag's) and its job, and the guess when there is one. A tagged row has no guess.
 */
export function filledRow(row: MyMailRow, held: { tagged: MyMailJobChip | null; line: MyMailLine | null; guess: MyMailGuess | null }, me?: string): MyMailRow {
  // A line this person's own tag wrote is theirs, drawn through `tagged`; `inMessages` names a line someone else holds
  // (the boxes' reader, or another person's tag), the one the tab cannot untag.
  const theirs = held.line && !(me && held.line.mail_user_id === me) ? held.line : null
  return {
    ...row,
    tagged: held.tagged ? { ...held.tagged, messageId: held.line?.id ?? null } : null,
    inMessages: theirs ? { messageId: theirs.id, jobKey: jobKeyOfRow(theirs) } : null,
    guess: held.tagged ? null : held.guess,
  }
}

/** Whether a row wants a guess: its conversation not tagged, the mail not folded, and no line of it on a job already. */
export function wantsGuess(row: Pick<MyMailRow, 'folded'>, held: { tagKey: string | null; line: MyMailLine | null }): boolean {
  return held.tagKey === null && row.folded === null && !(held.line && jobKeyOfRow(held.line))
}

// ---------- what a tag writes ----------

/** A line the tag found by its Message-ID, as `planTag` reads it. */
export interface MyMailHeldLine extends MyMailLine {
  rfc_message_id: string | null
  contact_id?: string | null
  mailbox?: string | null
}

/** `planTag`'s `known.byMessageId`: each line by its Message-ID, `mine` when this person's own box wrote it. */
export function knownLines(lines: readonly MyMailHeldLine[], userId: string): Record<string, MyMailKnownLine> {
  const out: Record<string, MyMailKnownLine> = {}
  for (const l of lines) {
    const rfc = (l.rfc_message_id ?? '').trim()
    if (!rfc || out[rfc]) continue
    out[rfc] = { messageId: l.id, jobKey: jobKeyOfRow(l), mine: l.mail_user_id === userId && l.mailbox === MY_MAIL_MAILBOX }
  }
  return out
}

/** The team's addresses for `planTag`'s `known.team`, as the bids@ reader gathers them (`gmail-sync`'s `loadTeam`). */
export function myMailTeam(users: readonly { id: string; name: string | null; email: string | null }[]): Record<string, { userId: string; name: string }> {
  const out: Record<string, { userId: string; name: string }> = {}
  for (const u of users) {
    const key = myMailAddressKey(u.email)
    if (key) out[key] = { userId: u.id, name: (u.name ?? '').trim() || key }
  }
  return out
}

type WriteStep = Extract<MyMailTagStep, { kind: 'write' }>

/**
 * The row `email_write_line` takes for a tagged mail, as `gmail-sync`'s `takeOne` builds one, column for column: the
 * invitation read off a mail in, the contact and the address it was placed on, the way, who wrote a mail out, who and
 * when, the subject and the words, the conversation, the box, the Message-ID and the job. The box is `mine` and the
 * person whose box it came from rides as `mail_user_id`.
 */
export function myMailLineRow(
  step: WriteStep,
  plan: Pick<MyMailTagPlan, 'mailbox' | 'mailUserId' | 'jobColumns'>,
  placed: { contactId: string; channelId: string | null },
  invitation: unknown = null,
): Record<string, unknown> {
  return {
    invitation,
    contact_id: placed.contactId,
    channel_id: placed.channelId,
    direction: step.direction,
    who_user_id: step.whoUserId,
    who_text: step.whoText,
    at: step.at,
    subject: step.subject,
    body: step.body,
    gmail_thread_id: step.threadId,
    mailbox: plan.mailbox,
    rfc_message_id: step.rfcMessageId,
    mail_user_id: plan.mailUserId,
    ...plan.jobColumns,
  }
}

/** The private bucket a tagged line's files and its raw copy go to, as the bids@ reader's files do. */
export const MY_MAIL_BUCKET = 'message-attachments'
/** The raw mail's type: the Legal desk's Evidence takes an email as `.eml` (`message/rfc822`). */
export const MY_MAIL_EML_MIME = 'message/rfc822'

/** A file's name as a path part, as the bids@ reader writes one: letters, digits, dots, dashes, underscores and spaces. */
export const safeFileName = (name: string): string => name.replace(/[^A-Za-z0-9._ -]+/g, '_').slice(0, 120) || 'file'

/**
 * Where a tagged mail's file is copied: under `mine/`, the person and the mail's Gmail id, as the reader's
 * `<gmail id>/<part>-<name>` but under the person, since a Gmail id is one box's own. `n` names a part with no id.
 */
export function myMailFilePath(userId: string, gmailId: string, partId: string, n: number, name: string): string {
  return `mine/${userId}/${gmailId}/${partId || n}-${safeFileName(name)}`
}

/** Where a tagged line's raw mail is kept as received: the court-ready copy the Legal desk's Evidence reads (PR 5). */
export const myMailEmlPath = (lineId: string): string => `mine/${lineId}.eml`

/**
 * A file row for `email_write_line`'s `p_files`, as `takeOne` writes one: a file host's link as a link; a file over 25 MB
 * left in Gmail as too big; a copied file at its path; one that would not copy left in Gmail as not copied.
 */
export function myMailFileRow(f: EmailFileRow, kept?: { path: string } | { left: 'not_copied' }): Record<string, unknown> {
  if (f.kind === 'link') return { kind: 'link', name: f.name, url: f.url, host: f.host }
  const base = { kind: 'file', name: f.name, mime: f.mime, size_bytes: f.size, gmail_attachment_id: f.attachmentId, paper: f.paper }
  if (f.keep === 'tooBig') return { ...base, left_in_gmail: 'too_big' }
  return kept && 'path' in kept ? { ...base, bucket_path: kept.path } : { ...base, left_in_gmail: 'not_copied' }
}

// ---------- what an untag removes ----------

/**
 * What an untag does: every line the person's own box wrote for the conversation goes, with its files and its raw copy;
 * a line the boxes wrote stays, and is untied only when the tag tied it (on the tag's job, last tied by this person).
 */
export function planUntag(input: { userId: string; tagJobKey: string | null; own: readonly Pick<MyMailLine, 'id'>[]; box: readonly MyMailLine[] }): { remove: string[]; untie: string[] } {
  const remove = [...new Set(input.own.map((l) => l.id))]
  const gone = new Set(remove)
  const untie =
    input.tagJobKey === null
      ? []
      : input.box.filter((l) => !gone.has(l.id) && !l.mail_user_id && l.tied_by === input.userId && jobKeyOfRow(l) === input.tagJobKey).map((l) => l.id)
  return { remove, untie: [...new Set(untie)] }
}
